package io.github.diodeme.ji.host;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/** Versioned opaque cursor bound to one Session timeline generation and fixed traversal direction. */
public final class TimelineCursorCodec {
    public static final String RESOURCE = "session-timeline";
    public static final String DIRECTION = "sequence-desc";

    private TimelineCursorCodec() {}

    public static String encode(String sessionId, long beforeSequence, long generation) {
        if (sessionId == null || sessionId.isBlank() || beforeSequence < 1 || generation < 1) {
            throw new IllegalArgumentException("invalid timeline cursor fields");
        }
        String raw = String.join("\n", "v1", RESOURCE, DIRECTION,
                Base64.getUrlEncoder().withoutPadding().encodeToString(sessionId.getBytes(StandardCharsets.UTF_8)),
                Long.toString(beforeSequence), Long.toString(generation));
        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
    }

    public static Cursor decode(String token, String sessionId) {
        if (sessionId == null || sessionId.isBlank()) throw new CursorException("binding");
        try {
            String raw = new String(Base64.getUrlDecoder().decode(token), StandardCharsets.UTF_8);
            String[] parts = raw.split("\n", -1);
            if (parts.length != 6 || !"v1".equals(parts[0])) throw new CursorException("malformed");
            if (!RESOURCE.equals(parts[1])) throw new CursorException("resource");
            if (!DIRECTION.equals(parts[2])) throw new CursorException("direction");
            String expectedSession = Base64.getUrlEncoder().withoutPadding()
                    .encodeToString(sessionId.getBytes(StandardCharsets.UTF_8));
            if (!expectedSession.equals(parts[3])) throw new CursorException("session");
            long sequence = Long.parseLong(parts[4]);
            long generation = Long.parseLong(parts[5]);
            if (sequence < 1 || generation < 1) throw new CursorException("malformed");
            return new Cursor(sequence, generation);
        } catch (CursorException failure) {
            throw failure;
        } catch (RuntimeException failure) {
            throw new CursorException("malformed", failure);
        }
    }

    public record Cursor(long beforeSequence, long generation) {}

    public static final class CursorException extends IllegalArgumentException {
        @java.io.Serial private static final long serialVersionUID = 1L;
        private final String reason;

        public CursorException(String reason) {
            super("invalid timeline cursor: " + reason);
            this.reason = reason;
        }

        public CursorException(String reason, Throwable cause) {
            super("invalid timeline cursor: " + reason, cause);
            this.reason = reason;
        }

        public String reason() { return reason; }
    }
}
